text:
{
 "lead": {
  "es": "大事《だいじ》なコンピューター（電子計算機《でんしけいさんき》）への悪《わる》い行《おこな》いで、害《がい》が出《で》ないようにする法律《ほうりつ》です。会社《かいしゃ》などがとどけたり知《し》らせたりすること、通信《つうしん》の情報《じょうほう》を集《あつ》めて調《しら》べること、見守《みまも》る委員会《いいんかい》をつくることなどを決《き》めます。",
  "hs": "重要な電子計算機（コンピューター）への不正な行為《こうい》による被害《ひがい》を防ぐため、事業者の届出・報告、通信情報の取得・分析《ぶんせき》、監督《かんとく》する委員会の設置などを定める法律です。"
 },
 "facts/0/text": {
  "es": "特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》（くらしを支《ささ》える大事《だいじ》な仕事《しごと》をする会社《かいしゃ》など）について決《き》めます。とくに大事《だいじ》なコンピューター（特定《とくてい》重要《じゅうよう》電子計算機《でんしけいさんき》）を入《い》れたら、国《くに》にとどけなければなりません。そのコンピューターへの悪《わる》い行《おこな》い（特定《とくてい》侵害《しんがい》事象《じしょう》等《とう》）が起《お》きたと気《き》づいたら、国《くに》に知《し》らせなければなりません。",
  "hs": "特別｜社会基盤《しゃかいきばん》事業者（電気や通信など社会の基盤《きばん》を支える事業者）に、特定重要電子計算機（特に重要なコンピューター）を導入したときの届出の義務と、そのコンピューターへの特定｜侵害《しんがい》事象等（不正な侵入《しんにゅう》など）の発生を認知したときの報告の義務を定めます。"
 },
 "facts/1/text": {
  "es": "内閣総理大臣《ないかくそうりだいじん》は、特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》など、通信《つうしん》を使《つか》う会社《かいしゃ》などと約束《やくそく》（協定《きょうてい》）を結《むす》べます。外国《がいこく》から国内《こくない》への通信《つうしん》（外内《がいない》通信《つうしん》）の情報《じょうほう》を使《つか》って調《しら》べることなどを約束《やくそく》します。そして、通信《つうしん》の情報《じょうほう》を受《う》け取《と》れます。また、外国《がいこく》からの悪《わる》い行《おこな》い（国外《こくがい》通信《つうしん》特定《とくてい》不正行為《ふせいこうい》）にかかわる通信《つうしん》があるかもしれません。外国《がいこく》どうし、外国《がいこく》から国内《こくない》、国内《こくない》から外国《がいこく》の通信《つうしん》（外外《がいがい》通信《つうしん》・外内《がいない》通信《つうしん》・内外《ないがい》通信《つうしん》）です。これが、外国《がいこく》にかかわる通信《つうしん》（国外《こくがい》関係《かんけい》通信《つうしん》）にふくまれると、うたがうだけのわけがあるときがあります。決《き》まった条件《じょうけん》にあえば、サイバー通信《つうしん》情報《じょうほう》監理《かんり》委員会《いいんかい》のみとめ（承認《しょうにん》）を受《う》けられます。そして、その通信《つうしん》の情報《じょうほう》の一部《いちぶ》をうつして、内閣総理大臣《ないかくそうりだいじん》が置《お》いた機械《きかい》に送《おく》らせることができます。",
  "hs": "内閣総理大臣は、特別｜社会基盤《しゃかいきばん》事業者などの通信サービスの利用者と、外内通信（外国から国内への通信）の情報を使った分析《ぶんせき》などを内容とする協定を結び、通信情報の提供を受けられます。また、国外通信特定｜不正行為《ふせいこうい》（国外からの不正な行為《こうい》）に関係する外外通信・外内通信・内外通信が国外関係通信に含《ふく》まれると疑うに足りる場合に、一定の要件を満たしたときは、サイバー通信情報｜監理《かんり》委員会の承認を受けて、その通信情報の一部を複製し、内閣総理大臣の設置する設備に送信させる措置《そち》（対応）をとれます。"
 },
 "facts/2/text": {
  "es": "内閣総理大臣《ないかくそうりだいじん》は、受《う》け取《と》った通信《つうしん》の情報《じょうほう》から、決《き》まった条件《じょうけん》にあう機械的《きかいてき》な情報《じょうほう》だけをえらびます。このような、通信《つうしん》の情報《じょうほう》のあつかい方《かた》の決《き》まりをつくります。内閣総理大臣《ないかくそうりだいじん》は、えらんだ情報《じょうほう》などを整理《せいり》して調《しら》べます。その情報《じょうほう》を、国《くに》の役所《やくしょ》や、特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》、コンピューターなどを売《う》る会社《かいしゃ》などに伝《つた》えます。このような決《き》まりもつくります。",
  "hs": "内閣総理大臣が取得した通信情報から、一定の要件を満たす機械的情報だけを選別する措置《そち》など、通信情報の扱《あつか》い方の規定を設けます。内閣総理大臣は選別した通信情報などを整理・分析《ぶんせき》し、その情報を国の行政機関、特別｜社会基盤《しゃかいきばん》事業者、電子計算機等供給者（コンピューターなどを供給する事業者）などに提供するなどの規定を設けます。"
 },
 "facts/3/text": {
  "es": "内閣総理大臣《ないかくそうりだいじん》と、関係《かんけい》する役所《やくしょ》の大臣《だいじん》などで、話《はな》し合《あ》いの会《かい》（協議会《きょうぎかい》）をつくります。大事《だいじ》なコンピューターへの悪《わる》い行《おこな》い（特定《とくてい》不正行為《ふせいこうい》）で、害《がい》が出《で》ないようにするための会《かい》です。情報《じょうほう》を分《わ》け合《あ》い、対策《たいさく》を話《はな》し合《あ》います。大事《だいじ》なコンピューターを使《つか》う人《ひと》なども、同意《どうい》があれば会《かい》に入《い》れられます。また、サイバー通信《つうしん》情報《じょうほう》監理《かんり》委員会《いいんかい》をつくります。この委員会《いいんかい》は、国《くに》などの大事《だいじ》なコンピューターなどへの悪《わる》い行《おこな》いをふせぐ取《と》り組《く》みが、正《ただ》しく行《おこな》われているかを調《しら》べ（審査《しんさ》）、たしかめ（検査《けんさ》）ます。",
  "hs": "内閣総理大臣と関係行政機関の長（関係する省庁の大臣など）で、重要電子計算機に対する特定｜不正行為《ふせいこうい》による被害《ひがい》を防ぐための情報共有・対策の協議会をつくり、重要電子計算機を使う人なども、同意を得て構成員に加えられます。また、サイバー通信情報｜監理《かんり》委員会を設置し、国などの重要なコンピューターなどへの不正な行為《こうい》の被害《ひがい》を防ぐ措置《そち》が適正に行われているかを確かめる審査《しんさ》と検査を任務とします。"
 },
 "facts/4/text": {
  "es": "衆議院《しゅうぎいん》で、法律《ほうりつ》の案《あん》が一部《いちぶ》直《なお》されました（修正《しゅうせい》）。直《なお》したのは、次《つぎ》のことです。通信《つうしん》のひみつを大事《だいじ》にすること。国会《こっかい》に知《し》らせることがらを、くわしく決《き》めること。通信《つうしん》の情報《じょうほう》についての約束《やくそく》・集《あつ》め方《かた》・あつかい方《かた》の決《き》まりを、使《つか》い始《はじ》めてから3年《ねん》をめどに見直《みなお》すことを考《かんが》える決《き》まりをつくること。",
  "hs": "衆議院で、通信の秘密の尊重、国会に対する報告事項《ほうこくじこう》の具体化、通信情報の協定・取得・取扱《とりあつか》いに関する規定の施行《しこう》（法律が効力をもつこと）後3年をめどにした検討規定の創設を内容とする修正が行われました。"
 },
 "facts/5/text": {
  "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞいて、世《よ》の中《なか》に知《し》らされた日《ひ》（公布《こうふ》）から1年《ねん》6か月《げつ》以内《いない》で、政令《せいれい》（内閣《ないかく》が決《き》めるきまり）で決《き》める日《ひ》から使《つか》われます。",
  "hs": "一部の規定を除き、公布（世の中に知らせること）の日から数えて1年6か月を超《こ》えない範囲《はんい》で、政令（内閣が決めるきまり）で定める日から施行《しこう》します。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、つぎのように説明《せつめい》しています。インターネットなどの、進《すす》んだ情報通信《じょうほうつうしん》のあみ（ネットワーク）が広《ひろ》がりました。情報通信《じょうほうつうしん》の技術《ぎじゅつ》を使《つか》うことも進《すす》みました。世界《せかい》のようすも、ふくざつになりました。そのため、国《くに》などの大事《だいじ》なコンピューターを悪《わる》い行《おこな》いから守《まも》ること（サイバーセキュリティ）が、もっと大切《たいせつ》になっています。そこで、害《がい》をふせぐため、次《つぎ》のことを決《き》める必要《ひつよう》がある、としています。もとになる方針《ほうしん》をつくること。特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》が、悪《わる》い行《おこな》い（特定《とくてい》侵害《しんがい》事象《じしょう》等《とう》）を知《し》らせるしくみ。通信《つうしん》の情報《じょうほう》を集《あつ》めること。サイバー通信《つうしん》情報《じょうほう》監理《かんり》委員会《いいんかい》が調《しら》べ（審査《しんさ》）、たしかめる（検査《けんさ》）こと。調《しら》べた結果《けっか》を伝《つた》えることなどです。",
  "hs": "内閣は、インターネットなどの高度情報通信ネットワークの整備や、情報通信技術の活用が進み、国際情勢も複雑になったとしている。そのため、国などの重要なコンピューター（電子計算機）のサイバーセキュリティ（不正な攻撃《こうげき》から守ること）を確保する重要性が増しているという。そこで被害《ひがい》を防ぐため、基本的な方針の策定、特別｜社会基盤《しゃかいきばん》事業者による特定｜侵害《しんがい》事象等の報告の制度、通信情報の取得、サイバー通信情報｜監理《かんり》委員会による審査《しんさ》と検査、分析《ぶんせき》結果の提供などを定める必要があるためとしている。"
 },
 "more/who/text": {
  "es": "特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》（くらしを支《ささ》える大事《だいじ》な仕事《しごと》をする会社《かいしゃ》など）にかかわります。決《き》められたとくに大事《だいじ》なコンピューターを入《い》れたら、国《くに》にとどけることになります。悪《わる》い行《おこな》い（特定《とくてい》侵害《しんがい》事象《じしょう》等《とう》）に気《き》づいたら、国《くに》に知《し》らせることになります。ほかに、内閣総理大臣《ないかくそうりだいじん》と約束《やくそく》（協定《きょうてい》）を結《むす》ぶ、通信《つうしん》を使《つか》う会社《かいしゃ》などにかかわります。外国《がいこく》にかかわる通信《つうしん》をつなぐ電気通信事業者《でんきつうしんじぎょうしゃ》にもかかわります。整理《せいり》して調《しら》べた情報《じょうほう》を受《う》け取《と》る、国《くに》の役所《やくしょ》や特別《とくべつ》社会基盤《しゃかいきばん》事業者《じぎょうしゃ》、コンピューターなどを売《う》る会社《かいしゃ》にもかかわります。話《はな》し合《あ》いの会《かい》（協議会《きょうぎかい》）に入《はい》ることができる、大事《だいじ》なコンピューターを使《つか》う人《ひと》などにもかかわります。",
  "hs": "特別｜社会基盤《しゃかいきばん》事業者（特定重要電子計算機の導入の届出と、特定｜侵害《しんがい》事象等の報告が義務になる）、内閣総理大臣と協定を結ぶ事業電気通信役務（通信サービス）の利用者、国外関係通信を媒介《ばいかい》する（つなぐ）電気通信事業者、整理・分析《ぶんせき》した情報の提供を受ける国の行政機関・特別｜社会基盤《しゃかいきばん》事業者・電子計算機等供給者、協議会に構成員として加わることができる重要電子計算機を使う人など。"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》の内閣委員会《ないかくいいんかい》は、関係《かんけい》する法律《ほうりつ》を整《ととの》える法律《ほうりつ》の案《あん》といっしょに話《はな》し合《あ》いました。くわしい人《ひと》（参考人《さんこうにん》）から意見《いけん》を聞《き》きました。総務委員会《そうむいいんかい》・安全保障委員会《あんぜんほしょういいんかい》と合同《ごうどう》で話《はな》し合《あ》う会《かい》も開《ひら》きました。石破《いしば》内閣総理大臣《ないかくそうりだいじん》に来《き》てもらって、質問《しつもん》もしました。自由民主党《じゆうみんしゅとう》・無所属《むしょぞく》の会《かい》、立憲民主党《りっけんみんしゅとう》・無所属《むしょぞく》、日本維新《にっぽんいしん》の会《かい》、国民民主党《こくみんみんしゅとう》・無所属《むしょぞく》クラブ、公明党《こうめいとう》、有志《ゆうし》の会《かい》が、いっしょに直《なお》す案《あん》（修正案《しゅうせいあん》）を出《だ》しました。通信《つうしん》のひみつや、国民《こくみん》の権利《けんり》と自由《じゆう》を、正《ただ》しくないかたちでせばめてはいけないことを、書《か》きこむ内容《ないよう》です。サイバー通信《つうしん》情報《じょうほう》監理《かんり》委員会《いいんかい》が国会《こっかい》に必《かなら》ず知《し》らせることがらを、ならべて書《か》くことなども内容《ないよう》です。賛成《さんせい》が多《おお》く、直《なお》して決《き》めることになりました。参議院《さんぎいん》の内閣委員会《ないかくいいんかい》も、総務委員会《そうむいいんかい》・外交防衛委員会《がいこうぼうえいいいんかい》と合同《ごうどう》で話《はな》し合《あ》う会《かい》を開《ひら》きました。くわしい人《ひと》（参考人《さんこうにん》）から意見《いけん》を聞《き》き、内閣総理大臣《ないかくそうりだいじん》に来《き》てもらって質問《しつもん》もしました。こちらから進《すす》んで動《うご》いてふせぐしくみ（能動的《のうどうてき》サイバー防御《ぼうぎょ》）を取《と》り入《い》れる意味《いみ》について、質問《しつもん》がありました。通信《つうしん》のひみつなど、憲法《けんぽう》と合《あ》っているかも聞《き》かれました。話《はな》し合《あ》いの会《かい》（協議会《きょうぎかい》）がきちんと役《やく》に立《た》つかも聞《き》かれました。国内《こくない》どうしの通信《つうしん》（内内《ないない》通信《つうしん》）の情報《じょうほう》のあつかいや、えらんだあとの通信《つうしん》の情報《じょうほう》の使《つか》い方《かた》も聞《き》かれました。相手《あいて》のコンピューターに入《はい》って害《がい》のないようにすること（アクセス・無害化《むがいか》）と、国《くに》と国《くに》のきまり（国際法《こくさいほう》）との関係《かんけい》も聞《き》かれました。中小企業《ちゅうしょうきぎょう》のサイバーセキュリティを強《つよ》くすることや、その支《ささ》え、人《ひと》を育《そだ》てて集《あつ》めることなども聞《き》かれました。決《けつ》をとった結果《けっか》、賛成《さんせい》が多《おお》く、もとの案《あん》のとおり決《き》めました。どちらの委員会《いいんかい》でも、委員会《いいんかい》からの注文《ちゅうもん》（附帯決議《ふたいけつぎ》）がつけられました。",
  "hs": "衆議院の内閣委員会は、関係法律の整備法案と一括《いっかつ》して審査《しんさ》した。参考人から意見を聞き、総務委員会・安全保障委員会との連合｜審査会《しんさかい》や、石破内閣総理大臣が出席した質疑も行った。自由民主党・無所属の会、立憲民主党・無所属、日本維新《にっぽんいしん》の会、国民民主党・無所属クラブ、公明党、有志の会の共同提案で修正案が出された。通信の秘密その他の国民の権利と自由を不当に制限してはならないことの明記や、サイバー通信情報｜監理《かんり》委員会が国会に必ず報告する事項《じこう》を並べることなどが内容で、賛成多数で修正議決すべきものとした。参議院の内閣委員会も、総務委員会・外交防衛委員会との連合｜審査会《しんさかい》、参考人からの意見聴取《いけんちょうしゅ》、内閣総理大臣が出席した質疑を行った。能動的サイバー防御《ぼうぎょ》（こちらから働きかけて防ぐしくみ）を導入する意義、通信の秘密をはじめとする憲法との整合性、協議会の実効性、内内通信（国内どうしの通信）の情報の扱《あつか》いと選別後の通信情報の利用のあり方、アクセス・無害化｜措置《そち》と国際法との関係、中小企業《ちゅうしょうきぎょう》のサイバーセキュリティの強化と支援《しえん》、人材の育成・確保などについて質疑があった。採決の結果、多数で原案どおり可決すべきものとした。両院の委員会で附帯決議《ふたいけつぎ》（委員会からの注文）がつけられた。"
 },
